CREATE TABLE week_plan (id UUID PRIMARY KEY, owner_sub VARCHAR(255) NOT NULL, week_start DATE NOT NULL, version BIGINT NOT NULL DEFAULT 0, UNIQUE(owner_sub, week_start));
CREATE TABLE planned_meal (id UUID PRIMARY KEY, plan_id UUID NOT NULL REFERENCES week_plan(id) ON DELETE CASCADE, recipe_id UUID NOT NULL, recipe_title VARCHAR(120) NOT NULL, meal_date DATE NOT NULL, slot VARCHAR(16) NOT NULL, portions INTEGER NOT NULL CHECK (portions > 0), ingredients_json VARCHAR(8000) NOT NULL, UNIQUE(plan_id, id));
CREATE TABLE shopping_list (id UUID PRIMARY KEY, plan_id UUID NOT NULL UNIQUE REFERENCES week_plan(id) ON DELETE CASCADE, source_version BIGINT NOT NULL, generated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE shopping_item (id UUID PRIMARY KEY, list_id UUID NOT NULL REFERENCES shopping_list(id) ON DELETE CASCADE, label VARCHAR(120) NOT NULL, quantity NUMERIC(12,3) NOT NULL, unit VARCHAR(20) NOT NULL, checked BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(list_id,label,unit));
